package main

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/didit-protocol/sdk-go/internal/naming"
)

const header = "// Code generated by codegen from openapi/*.json. DO NOT EDIT.\n\n"

// File is a generated file.
type File struct {
	Name    string
	Content []byte
}

// assignOwners records, for every declaration, the top-level resources whose
// methods reach it.
func (g *Gen) assignOwners(root *Service) {
	var visitType func(t *GoType, owner string)
	visited := map[string]map[string]bool{}
	visitType = func(t *GoType, owner string) {
		for t != nil && (t.Kind == TSlice || t.Kind == TMap) {
			t = t.Elem
		}
		if t == nil || t.Kind != TNamed {
			return
		}
		d := g.byName[t.Name]
		if d == nil {
			return
		}
		if visited[owner] == nil {
			visited[owner] = map[string]bool{}
		}
		if visited[owner][d.Name] {
			return
		}
		visited[owner][d.Name] = true
		d.Owners[owner] = true
		for _, f := range d.Fields {
			visitType(f.Type, owner)
		}
	}
	var walk func(s *Service)
	walk = func(s *Service) {
		for _, m := range s.Methods {
			if m.Params != nil {
				visitType(m.Params, s.Top)
			}
			if m.Result != nil {
				visitType(m.Result, s.Top)
			}
		}
		for _, c := range s.Children {
			walk(c)
		}
	}
	walk(root)
}

// assignPointers makes struct fields pointers where a by-value field would
// make a type contain itself.
func (g *Gen) assignPointers() {
	var contains func(from, target string, seen map[string]bool) bool
	contains = func(from, target string, seen map[string]bool) bool {
		if from == target {
			return true
		}
		if seen[from] {
			return false
		}
		seen[from] = true
		d := g.byName[from]
		if d == nil || d.Kind != DStruct {
			return false
		}
		for _, f := range d.Fields {
			if f.Pointer || f.Type.Kind != TNamed {
				continue
			}
			if contains(f.Type.Name, target, seen) {
				return true
			}
		}
		return false
	}
	for _, d := range g.sortedDecls() {
		if d.Kind != DStruct {
			continue
		}
		for _, f := range d.Fields {
			if f.Type.Kind != TNamed {
				continue
			}
			fd := g.byName[f.Type.Name]
			if fd == nil || fd.Kind != DStruct {
				continue
			}
			if contains(f.Type.Name, d.Name, map[string]bool{}) {
				f.Pointer = true
			}
		}
	}
}

// fileOf returns the file name of a declaration.
func fileOf(d *Decl) string {
	if len(d.Owners) == 1 {
		for o := range d.Owners {
			return o + "_gen.go"
		}
	}
	return "shared_gen.go"
}

// emit renders every generated file.
func (g *Gen) emit(root *Service) ([]File, error) {
	g.assignOwners(root)
	g.assignPointers()

	bodies := map[string]*bytes.Buffer{}
	buf := func(name string) *bytes.Buffer {
		if b, ok := bodies[name]; ok {
			return b
		}
		b := &bytes.Buffer{}
		bodies[name] = b
		return b
	}

	// Client and services.
	cb := buf("client_gen.go")
	emitClient(cb, root)
	var walk func(s *Service)
	walk = func(s *Service) {
		if s.Path != "" {
			emitService(buf(s.Top+"_gen.go"), s)
		}
		for _, c := range s.Children {
			walk(c)
		}
	}
	walk(root)

	// Types.
	for _, d := range g.sortedDecls() {
		if len(d.Owners) == 0 {
			continue
		}
		emitDecl(buf(fileOf(d)), d)
	}

	var files []File
	names := make([]string, 0, len(bodies))
	for n := range bodies {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		src := bodies[n].Bytes()
		full := assemble(src)
		formatted, err := format.Source(full)
		if err != nil {
			return nil, fmt.Errorf("formatting %s: %w\n%s", n, err, numbered(full))
		}
		files = append(files, File{Name: n, Content: formatted})
	}
	return files, nil
}

func numbered(src []byte) string {
	var b strings.Builder
	for i, line := range strings.Split(string(src), "\n") {
		fmt.Fprintf(&b, "%5d %s\n", i+1, line)
		if i > 4000 {
			break
		}
	}
	return b.String()
}

// assemble adds the header, package clause and the imports the body uses.
func assemble(body []byte) []byte {
	s := string(body)
	var std, mod []string
	for _, imp := range []struct{ pkg, use string }{
		{"context", "context."},
		{"encoding/json", "json."},
		{"net/http", "http."},
		{"time", "time."},
		{"github.com/didit-protocol/sdk-go/option", "option."},
	} {
		if !strings.Contains(s, imp.use) {
			continue
		}
		if strings.Contains(imp.pkg, ".") {
			mod = append(mod, strconv.Quote(imp.pkg))
		} else {
			std = append(std, strconv.Quote(imp.pkg))
		}
	}
	var b bytes.Buffer
	b.WriteString(header)
	b.WriteString("package didit\n\n")
	if len(std)+len(mod) > 0 {
		b.WriteString("import (\n")
		for _, imp := range std {
			b.WriteString("\t" + imp + "\n")
		}
		if len(std) > 0 && len(mod) > 0 {
			b.WriteString("\n")
		}
		for _, imp := range mod {
			b.WriteString("\t" + imp + "\n")
		}
		b.WriteString(")\n\n")
	}
	b.Write(body)
	return b.Bytes()
}

func emitClient(b *bytes.Buffer, root *Service) {
	b.WriteString("// Client is the Didit API client. Create it with NewClient; it is safe for\n// concurrent use. Each field is a resource of the API.\n")
	b.WriteString("type Client struct {\n\toptions []option.RequestOption\n\n")
	for _, c := range root.Children {
		fmt.Fprintf(b, "\t%s *%s\n", c.Field, c.TypeName)
	}
	b.WriteString("}\n\n")
	b.WriteString("func (c *Client) init() {\n")
	var walk func(s *Service, expr string)
	walk = func(s *Service, expr string) {
		for _, c := range s.Children {
			e := expr + "." + c.Field
			fmt.Fprintf(b, "\t%s = &%s{client: c}\n", e, c.TypeName)
			walk(c, e)
		}
	}
	walk(root, "c")
	b.WriteString("}\n\n")
}

func emitService(b *bytes.Buffer, s *Service) {
	writeDoc(b, "", fmt.Sprintf("%s holds the %s operations. Use it through Client.%s.", s.TypeName, strings.ReplaceAll(s.Path, ".", " "), clientPath(s)))
	fmt.Fprintf(b, "type %s struct {\n\tclient *Client\n", s.TypeName)
	if len(s.Children) > 0 {
		b.WriteString("\n")
	}
	for _, c := range s.Children {
		fmt.Fprintf(b, "\t%s *%s\n", c.Field, c.TypeName)
	}
	b.WriteString("}\n\n")
	for _, m := range s.Methods {
		emitMethod(b, s, m)
	}
}

func clientPath(s *Service) string {
	var parts []string
	for _, seg := range strings.Split(s.Path, ".") {
		parts = append(parts, naming.Pascal(seg))
	}
	return strings.Join(parts, ".")
}

func methodDoc(m *Method) string {
	op := m.Op.Node
	var parts []string
	summary := strings.TrimSpace(op.Get("summary").Text())
	desc := strings.TrimSpace(op.Get("description").Text())
	first := m.GoName
	if summary != "" {
		first += ": " + strings.TrimSuffix(summary, ".") + "."
	}
	parts = append(parts, first)
	if desc != "" && desc != summary {
		parts = append(parts, desc)
	}
	switch m.Return {
	case RetBinary:
		parts = append(parts, fmt.Sprintf("The response is a file (%s). Read it from the returned response's body and close it.", m.BinaryType))
	case RetPage:
		parts = append(parts, fmt.Sprintf("It returns one page; %sAutoPaging iterates over every item of every page.", m.GoName))
	}
	if m.Op.Naming.Scope == "application" {
		parts = append(parts, "The organization and application ids come from the client options.")
	}
	if dep := m.Op.Deprecated; dep != nil {
		parts = append(parts, dep.Notice())
	}
	return strings.Join(parts, "\n\n")
}

func emitMethod(b *bytes.Buffer, s *Service, m *Method) {
	writeDoc(b, "", methodDoc(m))
	fmt.Fprintf(b, "//\n//\t%s %s\n", m.Op.HTTPMethod, m.Op.Path)
	args := []string{"ctx context.Context"}
	for _, a := range m.PathArgs {
		args = append(args, a.Arg+" string")
	}
	if m.Params != nil {
		args = append(args, "params "+m.Params.Go())
	}
	args = append(args, "opts ...option.RequestOption")
	var ret string
	switch m.Return {
	case RetNone:
		ret = "error"
	case RetBinary:
		ret = "(*http.Response, error)"
	case RetPage:
		ret = fmt.Sprintf("(*Page[%s], error)", m.Result.Go())
	case RetJSON:
		ret = fmt.Sprintf("(%s, error)", resultType(m.Result))
	}
	fmt.Fprintf(b, "func (r *%s) %s(%s) %s {\n", s.TypeName, m.GoName, strings.Join(args, ", "), ret)
	req := requestLiteral(m)
	switch m.Return {
	case RetNone:
		fmt.Fprintf(b, "\t_, err := r.client.do(ctx, %s, nil, opts)\n\treturn err\n", req)
	case RetBinary:
		fmt.Fprintf(b, "\treturn r.client.do(ctx, %s, nil, opts)\n", req)
	case RetPage:
		fmt.Fprintf(b, "\treturn getPage[%s](ctx, r.client, %s, opts)\n", m.Result.Go(), req)
	case RetJSON:
		if m.Result.Kind == TNamed {
			fmt.Fprintf(b, "\tres := new(%s)\n\tif _, err := r.client.do(ctx, %s, res, opts); err != nil {\n\t\treturn nil, err\n\t}\n\treturn res, nil\n", m.Result.Go(), req)
		} else {
			fmt.Fprintf(b, "\tvar res %s\n\tif _, err := r.client.do(ctx, %s, &res, opts); err != nil {\n\t\treturn nil, err\n\t}\n\treturn res, nil\n", m.Result.Go(), req)
		}
	}
	b.WriteString("}\n\n")
	if m.Return == RetPage {
		writeDoc(b, "", fmt.Sprintf("%sAutoPaging iterates over every item of every page of %s, fetching pages as needed.", m.GoName, m.GoName))
		fmt.Fprintf(b, "func (r *%s) %sAutoPaging(%s) *PageIterator[%s] {\n", s.TypeName, m.GoName, strings.Join(args, ", "), m.Result.Go())
		var callArgs []string
		callArgs = append(callArgs, "ctx")
		for _, a := range m.PathArgs {
			callArgs = append(callArgs, a.Arg)
		}
		if m.Params != nil {
			callArgs = append(callArgs, "params")
		}
		callArgs = append(callArgs, "opts...")
		fmt.Fprintf(b, "\treturn newPageIterator(ctx, func() (*Page[%s], error) {\n\t\treturn r.%s(%s)\n\t})\n}\n\n", m.Result.Go(), m.GoName, strings.Join(callArgs, ", "))
	}
}

func resultType(t *GoType) string {
	if t.Kind == TNamed {
		return "*" + t.Go()
	}
	return t.Go()
}

func requestLiteral(m *Method) string {
	var fields []string
	fields = append(fields, "method: http.Method"+methodConst(m.Op.HTTPMethod))
	fields = append(fields, "path: "+strconv.Quote(m.Op.Path))
	if len(m.PathArgs) > 0 {
		var pp []string
		for _, a := range m.PathArgs {
			pp = append(pp, strconv.Quote(a.Name), a.Arg)
		}
		fields = append(fields, "pathParams: []string{"+strings.Join(pp, ", ")+"}")
	}
	if m.Op.Doc.Name == "account" {
		fields = append(fields, "api: apiAccount")
	}
	switch m.Op.Naming.Auth {
	case "account_token":
		fields = append(fields, "auth: authAccountToken")
	case "none":
		fields = append(fields, "auth: authNone")
	}
	if m.Op.Naming.Scope == "application" {
		fields = append(fields, "appScope: true")
	}
	if m.Params != nil {
		fields = append(fields, "params: params")
		if m.BodyKind != "bodyNone" {
			fields = append(fields, "body: "+m.BodyKind)
		}
	}
	if m.Return == RetBinary {
		fields = append(fields, "binary: true", "accept: "+strconv.Quote(m.Accept))
	}
	return "&apiRequest{" + strings.Join(fields, ", ") + "}"
}

func methodConst(m string) string {
	switch m {
	case "GET":
		return "Get"
	case "POST":
		return "Post"
	case "PUT":
		return "Put"
	case "PATCH":
		return "Patch"
	case "DELETE":
		return "Delete"
	}
	return m
}

func emitDecl(b *bytes.Buffer, d *Decl) {
	switch d.Kind {
	case DEnum:
		doc := fmt.Sprintf("%s is a string with known values below. The set is open: other values may appear and never cause an error.", d.Name)
		if d.Doc != "" {
			doc = d.Name + ": " + d.Doc + "\n\n" + doc
		}
		writeDoc(b, "", doc)
		fmt.Fprintf(b, "type %s string\n\n", d.Name)
		if len(d.Values) > 0 {
			fmt.Fprintf(b, "// Known values of %s.\nconst (\n", d.Name)
			for _, v := range d.Values {
				fmt.Fprintf(b, "\t%s %s = %s\n", v.GoName, d.Name, strconv.Quote(v.Value))
			}
			b.WriteString(")\n\n")
		}
	case DStruct:
		doc := d.Doc
		if doc == "" {
			if d.Side == Request {
				doc = fmt.Sprintf("%s is a request object.", d.Name)
			} else {
				doc = fmt.Sprintf("%s is a response object.", d.Name)
			}
		} else if !strings.HasPrefix(doc, d.Name+" ") {
			doc = d.Name + ": " + doc
		}
		writeDoc(b, "", doc)
		fmt.Fprintf(b, "type %s struct {\n", d.Name)
		for i, f := range d.Fields {
			if f.Doc != "" {
				if i > 0 {
					b.WriteString("\n")
				}
				fdoc := f.Doc
				if d.Side == Request && f.Required && f.Tag != "body" {
					fdoc += " Required."
				}
				writeDoc(b, "\t", fdoc)
			} else if d.Side == Request && f.Required && f.Tag != "body" {
				if i > 0 {
					b.WriteString("\n")
				}
				b.WriteString("\t// Required.\n")
			}
			fmt.Fprintf(b, "\t%s %s %s\n", f.GoName, fieldType(f), fieldTag(f))
		}
		if d.Side == Response {
			if len(d.Fields) > 0 {
				b.WriteString("\n")
			}
			b.WriteString("\t// JSON describes the decoded object: raw JSON, present, null and unknown\n\t// fields.\n\tJSON ResponseJSON `json:\"-\"`\n")
		}
		b.WriteString("}\n\n")
		if d.Side == Response {
			fmt.Fprintf(b, "// UnmarshalJSON decodes %s leniently.\nfunc (r *%s) UnmarshalJSON(data []byte) error {\n\treturn unmarshalResponse(data, r, &r.JSON)\n}\n\n", d.Name, d.Name)
		} else {
			fmt.Fprintf(b, "// MarshalJSON encodes the fields that are set.\nfunc (r %s) MarshalJSON() ([]byte, error) {\n\treturn marshalParams(r)\n}\n\n", d.Name)
		}
	}
}

func fieldType(f *Field) string {
	t := f.Type.Go()
	if f.Pointer {
		t = "*" + t
	}
	if f.Opt {
		return "Opt[" + t + "]"
	}
	return t
}

func fieldTag(f *Field) string {
	switch f.Tag {
	case "form":
		return fmt.Sprintf("`json:\"-\" form:%s`", strconv.Quote(f.Name))
	case "query":
		return fmt.Sprintf("`json:\"-\" query:%s`", strconv.Quote(f.Name))
	case "header":
		return fmt.Sprintf("`json:\"-\" header:%s`", strconv.Quote(f.Name))
	case "body":
		return "`json:\"-\" body:\"json\"`"
	}
	return fmt.Sprintf("`json:%s`", strconv.Quote(f.Name))
}

// cleanText normalises a description for a Go comment.
func cleanText(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "—", " - ")
	s = strings.ReplaceAll(s, "–", "-")
	return s
}

// writeDoc writes text as a wrapped // comment.
func writeDoc(b *bytes.Buffer, indent, text string) {
	text = strings.TrimSpace(cleanText(text))
	if text == "" {
		return
	}
	const width = 77
	paragraphs := strings.Split(text, "\n\n")
	for pi, p := range paragraphs {
		if pi > 0 {
			b.WriteString(indent + "//\n")
		}
		lines := strings.Split(p, "\n")
		// Keep list items and code-like lines on their own lines.
		var merged []string
		for _, l := range lines {
			l = strings.TrimRight(l, " \t")
			trim := strings.TrimSpace(l)
			if trim == "" {
				continue
			}
			isItem := strings.HasPrefix(trim, "- ") || strings.HasPrefix(trim, "* ") || strings.HasPrefix(trim, "|") || (len(trim) > 2 && trim[0] >= '0' && trim[0] <= '9' && strings.HasPrefix(strings.TrimLeft(trim, "0123456789"), ". "))
			if len(merged) == 0 || isItem {
				merged = append(merged, trim)
			} else {
				merged[len(merged)-1] += " " + trim
			}
		}
		for _, l := range merged {
			switch {
			case strings.HasPrefix(l, "|"):
				b.WriteString(indent + "//\t" + l + "\n")
			case strings.HasPrefix(l, "- ") || strings.HasPrefix(l, "* "):
				wrapItem(b, indent, "   - ", "     ", strings.TrimSpace(l[2:]), width)
			case len(l) > 2 && l[0] >= '0' && l[0] <= '9' && strings.HasPrefix(strings.TrimLeft(l, "0123456789"), ". "):
				num := l[:len(l)-len(strings.TrimLeft(l, "0123456789"))]
				wrapItem(b, indent, "   "+num+". ", strings.Repeat(" ", len(num)+5), strings.TrimSpace(l[len(num)+2:]), width)
			default:
				wrap(b, indent, l, width)
			}
		}
	}
}

// wrapItem writes a list item: first line after marker, the next ones after
// cont (the indentation gofmt uses for doc comment lists).
func wrapItem(b *bytes.Buffer, indent, marker, cont, text string, width int) {
	words := strings.Fields(text)
	cur := marker
	empty := true
	for _, w := range words {
		if !empty && utf8.RuneCountInString(cur)+1+utf8.RuneCountInString(w) > width {
			b.WriteString(indent + "//" + cur + "\n")
			cur = cont + w
			continue
		}
		if empty {
			cur += w
			empty = false
		} else {
			cur += " " + w
		}
	}
	b.WriteString(indent + "//" + cur + "\n")
}

func wrap(b *bytes.Buffer, indent, line string, width int) {
	words := strings.Fields(line)
	cur := ""
	for _, w := range words {
		if cur != "" && utf8.RuneCountInString(cur)+1+utf8.RuneCountInString(w) > width {
			b.WriteString(indent + "// " + cur + "\n")
			cur = w
			continue
		}
		if cur == "" {
			cur = w
		} else {
			cur += " " + w
		}
	}
	if cur != "" {
		b.WriteString(indent + "// " + cur + "\n")
	}
}
